SNAPS_AR=[
{"lab":"سبتمبر ’14","t":"الحوثيون يسيطرون على صنعاء","sum":"يسيطر مقاتلو الحوثيين القادمون من معقلهم الشمالي في صعدة على صنعاء خلال أيام قليلة. وتبقى حكومة هادي في منصبها، وينتشر الحوثيون في محافظات أخرى خلال الأشهر التالية.","notes":{"capital":"سيطر عليها الحوثيون في 21 سبتمبر 2014."}},
{"lab":"مارس ’15","t":"تدخل التحالف","sum":"قوات بقيادة الحوثيين تسيطر على لحج وتصل إلى أطراف عدن. الرئيس هادي يغادر البلاد، وفي 26 مارس يبدأ تحالف بقيادة السعودية غاراته الجوية.","notes":{"aden":"وصلت القوات بقيادة الحوثيين إلى أطرافها في 25 مارس، وكان هادي قد فرّ من صنعاء إلى عدن قبل شهر.","lahij":"سيطرت عليها قوات بقيادة الحوثيين في 25 مارس 2015."}},
{"lab":"ديسمبر ’15","t":"استعادة الجنوب وحصار تعز","sum":"قوات مدعومة من التحالف تستعيد عدن ومعظم الجنوب في منتصف 2015. وتصبح تعز مدينة منقسمة ومحاصرة. وينتزع تنظيم القاعدة في جزيرة العرب المكلا ويحتفظ بالساحل الحضرمي.","notes":{"hadramawt":"سيطر تنظيم القاعدة في جزيرة العرب على المكلا والساحل منذ أبريل 2015. وسيطرت الحكومة على الداخل.","taiz":"منقسمة بين قوات موالية للحكومة وقوات حوثية، والمدينة تحت الحصار."}},
{"lab":"أبريل ’16","t":"استعادة المكلا من القاعدة","sum":"قوات مدعومة من الإمارات والتحالف تستعيد المكلا من تنظيم القاعدة في جزيرة العرب، منهيةً سيطرته على الساحل الحضرمي. وخطوط الشمال بالكاد تتحرك.","notes":{"hadramawt":"استُعيدت المكلا في 24 أبريل 2016."}},
{"lab":"ديسمبر ’18","t":"جبهة الحديدة وستوكهولم","sum":"قوات الساحل الغربي، ومنها القوات التي يقودها طارق صالح، تتقدم على امتداد ساحل البحر الأحمر وتسيطر على الجزء الجنوبي من محافظة الحديدة. واتفاق ستوكهولم المؤرخ في 13 ديسمبر 2018 يوقف القتال على مدينة الحديدة وميناءها.","notes":{"hodeidah":"احتفظ الحوثيون بالمدينة والميناء. وسيطرت قوات مدعومة من التحالف على الساحل جنوبًا، ومنه المخا."}},
{"lab":"نوفمبر ’19","t":"المجلس الانتقالي يسيطر على عدن","sum":"في أغسطس 2019 يسيطر المجلس الانتقالي المدعوم من الإمارات على عدن من القوات الموالية للحكومة. وتدفع القوات الحكومية بالقتال في شبوة وأبين. واتفاق الرياض المؤرخ في 5 نوفمبر يحاول دمج المعسكرين.","notes":{"aden":"سيطر المجلس الانتقالي على المدينة في أغسطس 2019.","abyan":"تنازع عليها المجلس الانتقالي والقوات الحكومية بعد أغسطس 2019."}},
{"lab":"يونيو ’20","t":"سقوط الجوف والسيطرة على سقطرى","sum":"يسيطر الحوثيون على الحزم، عاصمة الجوف، في مارس 2020 ويضغطون باتجاه مأرب. ويعلن المجلس الانتقالي الإدارة الذاتية في عدن في أبريل، ثم يسيطر على سقطرى في يونيو.","notes":{"jawf":"سقطت الحزم في 1 مارس 2020. وقد تبقى جيوب صغيرة خارج سيطرة الحوثيين.","marib":"يسيطر الحوثيون على المديريات الغربية. وتسيطر الحكومة على مدينة مأرب والشرق.","socotra":"سيطر المجلس الانتقالي على حديبو في 19 يونيو 2020."}},
{"lab":"نوفمبر ’21","t":"هجوم مأرب","sum":"يتصاعد الهجوم الحوثي على مأرب طوال 2021، ويسيطرون على بيحان ومديريات مجاورة في شبوة. وفي نوفمبر تنسحب قوات موالية للحكومة من أجزاء من جبهة الحديدة.","notes":{"shabwa":"سيطر الحوثيون على بيحان وعسيلان وعين في سبتمبر 2021.","hodeidah":"تغيرت خطوط الجبهة على الساحل الجنوبي بعد إعادة الانتشار في نوفمبر."}},
{"lab":"أبريل ’22","t":"الهدنة ومجلس القيادة","sum":"ألوية العمالقة تستعيد بيحان وعسيلان وعين في يناير. وتبدأ هدنة برعاية الأمم المتحدة في 2 أبريل، ويحل مجلس القيادة الرئاسي محل هادي في 7 أبريل.","notes":{"shabwa":"عُكست المكاسب الحوثية في غرب المحافظة في يناير 2022."}},
{"lab":"نوفمبر ’22","t":"المجلس الانتقالي يسيطر على شبوة وأبين","sum":"في أغسطس 2022 يسيطر المجلس الانتقالي وقوات حليفة على معظم شبوة وأبين، ويستولون على حقول النفط ويضعفون الحكومة وحزب الإصلاح. ومنذ سبتمبر يتجه الهجوم إلى معاقل القاعدة.","notes":{"shabwa":"سقطت عتق في أغسطس 2022.","abyan":"السيطرة على شقرة وأحور ولودر في أغسطس 2022.","hadramawt":"بقي وادي الداخل مع قوات موالية للحكومة. وكان الساحل بيد قوات موالية للمجلس الانتقالي."}},
{"lab":"ديسمبر ’25","t":"المجلس الانتقالي يجتاح الشرق","sum":"منذ 2 ديسمبر يسيطر المجلس الانتقالي على حضرموت والمهرة، بما في ذلك حقول النفط ومدينة سيئون. وبحلول 9 ديسمبر يزعم سيطرته على كل محافظات اليمن الجنوبي السابق. وقدّر أحد التقديرات أن المجلس الانتقالي يسيطر على 52% من أراضي اليمن والحوثيين على 33%.","notes":{"hadramawt":"سيطر المجلس الانتقالي وقوات النخبة الحضرمية على سيئون والساحل.","mahrah":"سيطر عليها المجلس الانتقالي في ديسمبر 2025."}},
{"lab":"يناير ’26","t":"الحكومة تستعيد الجنوب","sum":"هجوم مضاد مدعوم من السعودية انطلق في 2 يناير يستعيد سيئون (3 يناير) والمكلا (4 يناير) وعدن (7 يناير). والمجلس الانتقالي يعلن حل نفسه في 9 يناير، رغم أن بعض قياداته تنفي ذلك.","notes":{"aden":"دخلتها القوات الحكومية في 7 يناير 2026.","socotra":"أفادت التقارير بانتقالها إلى سيطرة الحكومة. والتقارير محدودة.","dhale":"أفيد بأنها تحت سيطرة الحكومة. والمجلس الانتقالي ينازع في ادعاء السيطرة الكاملة."}},
{"lab":"سبتمبر ’26","t":"الحوثيون يسيطرون على ساحل البحر الأحمر","sum":"تنهار هدنة 2022 في يوليو. وفي 3 سبتمبر يشن الحوثيون هجومًا على باب المندب، ويسيطرون على المخا في 10 سبتمبر وعلى ميون وجزر حنيش في 11 سبتمبر. ونزح أكثر من 100 ألف شخص.","notes":{"hodeidah":"الحوثيون يعلنون السيطرة على كامل الساحل. وقالت الحكومة في 6 سبتمبر إنها استعادت مديرية حيس، لذا فهذه المنطقة متنازع عليها.","taiz":"انتقلت المخا، على ساحل هذه المحافظة، إلى الحوثيين. ويستمر القتال حول مدينة تعز."}},
{"lab":"أكتوبر ’26","t":"هجوم حكومي على صنعاء","sum":"في 4 أكتوبر يأمر رئيس مجلس القيادة الرئاسي رشاد العليمي القوات باستعادة كل الأراضي التي يسيطر عليها الحوثيون. وتقول الحكومة إنها سيطرت على ذباب والمخا وإنها تهاجم صنعاء؛ والحوثيون ينفون ذلك ولم يتأكد أي منها من مصدر مستقل. وتفيد التقارير بأن الحوثيين قطعوا آخر طريق بين تعز وعدن.","notes":{"taiz":"ادعاءات الحكومة بشأن المخا وذباب غير مؤكدة. وقتال عنيف حول جبل حان.","marib":"هجمات حكومية على جبهة رغوان في الشمال. وقُصفت جوًا مواقع حوثية قرب جبل هيلان."}},
{"lab":"أكتوبر ’26","t":"ضربات على مطارات سعودية وقتال حول تعز","sum":"بين 6 و14 أكتوبر أصابت هجمات حوثية بالصواريخ والطائرات المسيّرة مطاري الرياض وأبها ومنشأة لأرامكو في الظهران. وقُتل 20 شخصًا على الأقل وأصيب أكثر من 370 في هجمات المطارات حتى 12 أكتوبر. وتقول الحكومة إن هجومها «فجر اليمن» تقدم في مأرب والجوف، وإن التحالف ضرب صنعاء وصعدة. ومدينة تعز تحت الحصار، ونزح أكثر من 233 ألف شخص.","notes":{"taiz":"قتال عنيف على الأطراف الغربية والجنوبية. ومنظمة الصحة العالمية تصف المدينة بأنها معزولة عمليًا.","marib":"القوات الحكومية تزعم تحقيق مكاسب في الشمال الغربي والجنوب. والحوثيون يسيطرون على غرب المحافظة.","jawf":"القوات الحكومية ومقاتلون حلفاء تواصل هجومًا. والحوثيون يسيطرون على معظم المحافظة."}},
]
OUTLOOK_AR={"note":"هذه قراءات تحريرية للمصادر المدرجة، وليست توقعًا إحصائيًا. والتصنيفات تقريبية. راجعوا التقارير المرتبطة واعتبروها نقطة انطلاق.","items":[
{"q":"هل ستحافظ القوات الحكومية على مرتفعات تعز وتعيد فتح الطريق إلى عدن؟","why":["قال المحلل رايمان الحمداني للجزيرة إن القوات الحكومية قادرة على الإبقاء على خطوطها لكنها لا تستطيع حاليًا إزاحة الحوثيين.","قطع الحوثيون طريق تعز–عدن الرئيسي في 4 أكتوبر، وتصف منظمة الصحة العالمية مدينة تعز بأنها معزولة عمليًا.","يعلن الطرفان عن مكاسب محلية غرب تعز وجنوبها. ولم يتأكد أي من الادعاءين من مصدر مستقل."],"watch":"سيطرة مؤكدة على التربة أو على الطريق إلى عدن، أو وصول الوقود والمساعدات إلى مدينة تعز."},
{"q":"هل ستستمر الهجمات الحوثية بالصواريخ والطائرات المسيّرة على السعودية خلال الأيام الثلاثين المقبلة؟","why":["أُفيد بهجمات على الرياض وأبها والدمام والظهران في معظم الأيام بين 6 و14 أكتوبر.","قال متحدث باسم الحوثيين إن العمليات ستستمر.","قال مجلس الوزراء السعودي إنه لن يسمح بتهديد أمنه أو الملاحة في البحر الأحمر، ويفيد التحالف باعتراض صواريخ."],"watch":"عدة أيام دون إطلاق، أو إعلان بوساطة من سلطنة عُمان."},
{"q":"هل سيبدأ سريان وقف إطلاق النار خلال 30 يومًا؟","why":["اقترحت السعودية بحسب التقارير وقفًا لإطلاق النار لأسبوعين بوساطة عُمانية في منتصف سبتمبر، وتوسع القتال والضربات بعد ذلك.","يتوقع الحمداني تسوية تفاوضية غير كاملة على المدى الطويل، لكنه يقول إن بلوغها قد يتطلب أولًا تصعيدًا جديًا.","يشير تقييم منظمة أكليد (ACLED) في 16 أكتوبر إلى تزايد خطر نزاع طويل الأمد."],"watch":"تصريحات علنية من سلطنة عُمان أو من المبعوث الأممي هانس غروندبرغ، أو توقف الضربات على المطارات."},
{"q":"هل ستصل القوات الحكومية إلى صنعاء بحلول نهاية 2026؟","why":["يسيطر الحوثيون على معاقل جبلية لم تتمكن القوات الحكومية من السيطرة عليها بحسب التقارير.","التقدم المعلن حتى الآن في مأرب والجوف وتعز، وليس على مشارف صنعاء.","توصف القوات البرية الحكومية بأنها كبيرة على الورق لكنها موزعة على جبهات كثيرة بمعدات قديمة."],"watch":"سيطرة مؤكدة على مديرية في محافظة صنعاء أو عمران."}]}
